// 完整cold算法仍唯一语义参照；此处只建立不可变平衡区间树和同candidate opaque热凭据。
#include "validated_facility_index.hpp"
#include "resident/kernel/world_bundle.hpp"
#include <algorithm>
#include <map>
#include <set>
#include <stdexcept>
#include <tuple>
namespace hanmo::resident {namespace {
struct Failure{RuleError error;};
void fail(const char* code){throw Failure{common_failure(code,"facility_index").error};}
template<class T>T take(Outcome<T> result){if(!result.ok)throw Failure{std::move(result.error)};return std::move(result.value);}
template<class T,class F>Outcome<T> guard(F fn){try{return {true,fn(),{}};}catch(Failure& e){return {false,{},std::move(e.error)};}catch(const std::bad_alloc&){return {false,{},common_failure("FacilityIndexResourceExhausted","facility_index",ErrorKind::internal).error};}catch(const std::length_error&){return {false,{},common_failure("FacilityIndexResourceExhausted","facility_index",ErrorKind::internal).error};}}
int compare(const WorldMoment& a,const WorldMoment& z,ExactArithmeticBudget budget){return take(compare_world_moments(a,z,budget));}
auto domain_key(const DomainReadKey& key){return std::tie(key.domain,key.kind,key.id);}
void key_value(const DomainReadKey& key){if(key.domain.empty()||key.kind.empty()||key.id.empty())fail("MissingFacilityIndexDependency");}
using UnitKey=std::tuple<StableId,unsigned,StableId,StableId,StableId,Integer,StableId>;
UnitKey unit_key(const FacilityPhysicalUnitRef& u){if(u.facility_id.empty()||u.unit_key.empty())fail("InvalidFacilityIndexUnit");if(const auto* installed=std::get_if<InstalledPhysicalUnitSource>(&u.installation_source_ref)){if(!valid_source_ref(installed->source_ref)||installed->source_schema==0)fail("InvalidFacilityIndexInstallation");return {u.facility_id,0,installed->source_ref.domain,installed->source_ref.kind,installed->source_ref.id,installed->source_schema,u.unit_key};}const auto& activated=std::get<ActivatedPhysicalUnitSource>(u.installation_source_ref).original_facility_activation_receipt_ref;if(activated.receipt_id.empty()||activated.source_schema==0)fail("InvalidFacilityIndexActivation");return {u.facility_id,1,{},{},activated.receipt_id,activated.source_schema,u.unit_key};}
struct Interval{StableId claim_id;WorldMoment from,until;};
struct Node{Interval value;WorldMoment maximum_until;std::shared_ptr<const Node> left,right;};
using Tree=std::shared_ptr<const Node>;
Tree build(const std::vector<Interval>& rows,std::size_t begin,std::size_t end,ExactArithmeticBudget budget){if(begin==end)return {};const auto middle=begin+(end-begin)/2;auto node=std::make_shared<Node>();node->value=rows[middle];node->left=build(rows,begin,middle,budget);node->right=build(rows,middle+1,end,budget);node->maximum_until=node->value.until;for(const auto* child:{&node->left,&node->right})if(*child&&compare(node->maximum_until,(*child)->maximum_until,budget)<0)node->maximum_until=(*child)->maximum_until;return node;}
Tree make_tree(std::vector<Interval>& rows,ExactArithmeticBudget budget){std::sort(rows.begin(),rows.end(),[&](const auto& a,const auto& z){const auto c=compare(a.from,z.from,budget);return c?c<0:a.claim_id<z.claim_id;});return build(rows,0,rows.size(),budget);}
void collect(const Tree& node,const MomentSpan& span,std::vector<StableId>& output,ExactArithmeticBudget budget){if(!node||compare(node->maximum_until,span.from,budget)<=0)return;if(node->left)collect(node->left,span,output,budget);if(compare(node->value.from,span.to,budget)<0){if(compare(span.from,node->value.until,budget)<0)output.push_back(node->value.claim_id);collect(node->right,span,output,budget);}}
}
struct ValidatedFacilityIndex::Data {
    struct Slot{Tree claims;std::map<UnitKey,Tree> units;};
    std::map<FacilitySlotRef,Slot> slots;
};
ValidatedFacilityIndex::ValidatedFacilityIndex()=default;
ValidatedFacilityIndex::~ValidatedFacilityIndex()=default;
ValidatedFacilityIndex::ValidatedFacilityIndex(const ValidatedFacilityIndex& other):data_(other.data_),dirty_slots_(other.dirty_slots_){}
ValidatedFacilityIndex& ValidatedFacilityIndex::operator=(const ValidatedFacilityIndex& other){if(this!=&other){auto data=other.data_;auto dirty=other.dirty_slots_;data_=std::move(data);dirty_slots_=std::move(dirty);ticket_.reset();}return *this;}
void ValidatedFacilityIndex::invalidate()noexcept{ticket_.reset();}
void ValidatedFacilityIndex::mark_dirty(const FacilitySlotRef& slot){ticket_.reset();if(std::find(dirty_slots_.begin(),dirty_slots_.end(),slot)==dirty_slots_.end())dirty_slots_.push_back(slot);}
Status ValidatedFacilityIndex::validate_ticket(const ReadStampAuthority& authority,const WorldIdentity& identity,const CommonRead& common,const DomainReadVersionSource& versions)const{if(!ticket_||!data_||!dirty_slots_.empty())return common_failure("FacilityIndexRequiresRevalidation");return authority.validate(*ticket_,identity,ReadMode::phase_current,common,versions);}
Status ValidatedFacilityIndex::rebuild(const WorldBundle& world,const FacilityClaimsState& state,const FacilityClaimsCatalog& catalog,const WorldMoment& now,const FacilityClaimSourceRead& sources,const FacilityIndexDependencyRead& dependencies,const CurrentReadStampRead& current,const ReadStampAuthority& authority,const WorldIdentity& identity,const CommonRead& common,const DomainReadVersionSource& versions,ExactArithmeticBudget budget){return guard<Done>([&]{
    // 先废旧票。失败保留纯派生数据供丢弃，不容旧certificate跨失败/rollback复活。
    ticket_.reset();if(!world.facility_claims||&state!=&*world.facility_claims||&common!=&world.common||!world.catalog)fail("FacilityIndexCandidateRootMismatch");std::vector<ResourceKey> resources;std::vector<DomainReadKey> domains;std::vector<StableId> facts;
    for(const auto& slot:catalog.selected_slots){auto d=take(dependencies.read_facility_index_dependencies(slot));key_value(d.slot_neighborhood);key_value(d.capacity_source_collection);key_value(d.holder_source_collection);if(domain_key(d.slot_neighborhood)==domain_key(d.capacity_source_collection)||domain_key(d.slot_neighborhood)==domain_key(d.holder_source_collection)||domain_key(d.capacity_source_collection)==domain_key(d.holder_source_collection))fail("AliasedFacilityIndexCollections");take(dependencies.validate_facility_index_dependency_coverage(slot,d));domains.push_back(d.slot_neighborhood);domains.push_back(d.capacity_source_collection);domains.push_back(d.holder_source_collection);for(const auto& key:d.original_dependencies){key_value(key);domains.push_back(key);}resources.insert(resources.end(),d.resources.begin(),d.resources.end());facts.insert(facts.end(),d.actual_common_fact_ids.begin(),d.actual_common_fact_ids.end());}
    std::sort(resources.begin(),resources.end(),[](const auto& a,const auto& z){return std::tie(a.kind,a.id)<std::tie(z.kind,z.id);});resources.erase(std::unique(resources.begin(),resources.end(),[](const auto& a,const auto& z){return a.kind==z.kind&&a.id==z.id;}),resources.end());
    std::sort(domains.begin(),domains.end(),[](const auto& a,const auto& z){return domain_key(a)<domain_key(z);});domains.erase(std::unique(domains.begin(),domains.end(),[](const auto& a,const auto& z){return domain_key(a)==domain_key(z);}),domains.end());std::sort(facts.begin(),facts.end());facts.erase(std::unique(facts.begin(),facts.end()),facts.end());
    auto ticket=take(current.capture(resources,domains,facts));if(!ticket||ticket->mode()!=ReadMode::phase_current||compare(take(world.actual_phase_moment()),now,budget)!=0)fail("FacilityIndexMomentMismatch");take(authority.validate(*ticket,identity,ReadMode::phase_current,common,versions));
    take(validate_facility_claims(state,catalog,now,sources,budget));auto data=std::make_shared<Data>();
    struct Rows{std::vector<Interval> claims;std::map<UnitKey,std::vector<Interval>> units;};std::map<FacilitySlotRef,Rows> grouped;for(const auto& slot:catalog.selected_slots)if(!grouped.emplace(slot,Rows{}).second)fail("DuplicateFacilityIndexSlot");
    for(const auto& c:state.claims){auto found=grouped.find(c.slot_ref);if(found==grouped.end())fail("UnselectedFacilityIndexSlot");auto& rows=found->second;Interval interval{c.claim_id,c.from,c.until};rows.claims.push_back(interval);auto actual=take(dependencies.read_facility_index_units(c));if(!actual.empty()&&actual.size()!=static_cast<std::size_t>(c.units))fail("FacilityIndexPhysicalUnitCountMismatch");std::set<UnitKey> unique;for(const auto& u:actual){if(u.facility_id!=c.slot_ref.facility_id)fail("FacilityIndexPhysicalFacilityMismatch");auto key=unit_key(u);if(!unique.insert(key).second)fail("DuplicateFacilityIndexPhysicalUnit");rows.units[key].push_back(interval);}}
    for(auto& group:grouped){Data::Slot entry;entry.claims=make_tree(group.second.claims,budget);for(auto& unit:group.second.units)entry.units.emplace(unit.first,make_tree(unit.second,budget));data->slots.emplace(group.first,std::move(entry));}
    take(authority.validate(*ticket,identity,ReadMode::phase_current,common,versions));data_=std::move(data);ticket_=std::move(ticket);dirty_slots_.clear();return Done{};
});}
Outcome<std::vector<StableId>> ValidatedFacilityIndex::overlapping_claims(const FacilitySlotRef& slot,const MomentSpan& span,const ReadStampAuthority& authority,const WorldIdentity& identity,const CommonRead& common,const DomainReadVersionSource& versions,ExactArithmeticBudget budget)const{return guard<std::vector<StableId>>([&]{take(validate_ticket(authority,identity,common,versions));take(make_moment_span(span.from,span.to,budget));auto found=data_->slots.find(slot);if(found==data_->slots.end())fail("UnselectedFacilityIndexSlot");std::vector<StableId> out;if(compare(span.from,span.to,budget)==0)return out;collect(found->second.claims,span,out,budget);return out;});}
Outcome<std::vector<StableId>> ValidatedFacilityIndex::overlapping_physical_claims(const FacilitySlotRef& slot,const FacilityPhysicalUnitRef& unit,const MomentSpan& span,const ReadStampAuthority& authority,const WorldIdentity& identity,const CommonRead& common,const DomainReadVersionSource& versions,ExactArithmeticBudget budget)const{return guard<std::vector<StableId>>([&]{take(validate_ticket(authority,identity,common,versions));take(make_moment_span(span.from,span.to,budget));if(unit.facility_id!=slot.facility_id)fail("FacilityIndexPhysicalFacilityMismatch");auto found=data_->slots.find(slot);if(found==data_->slots.end())fail("UnselectedFacilityIndexSlot");std::vector<StableId> out;const auto physical_key=unit_key(unit);if(compare(span.from,span.to,budget)==0)return out;auto tree=found->second.units.find(physical_key);if(tree!=found->second.units.end())collect(tree->second,span,out,budget);return out;});}
}
